// Custom "button" built from a div: Enter on keydown, Space on keyup.
// Tiny fake element: just enough to dispatch key events.
function makeFakeDiv() {
  const handlers = {};
  return {
    on(type, fn) { handlers[type] = fn; },
    fire(type, key) {
      const e = { key, prevented: false, preventDefault() { this.prevented = true; } };
      if (handlers[type]) handlers[type](e);
      return e;
    },
  };
}

let clicks = 0;
const el = makeFakeDiv();
const activate = () => { clicks++; };

// Native button contract: Enter fires on keydown, Space fires on keyup.
el.on('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); activate(); }
  if (e.key === ' ') e.preventDefault(); // stop the page from scrolling
});
el.on('keyup', (e) => {
  if (e.key === ' ') activate(); // lets the user press, change their mind, move away
});

const steps = [['keydown', 'Enter'], ['keydown', ' '], ['keyup', ' '], ['keydown', 'a']];
for (const [type, key] of steps) {
  const e = el.fire(type, key);
  console.log(type + ' ' + JSON.stringify(key) + ' -> clicks=' + clicks + ' scrollBlocked=' + e.prevented);
}
console.log('total activations:', clicks); // Enter once + Space once = 2

// Simplified accessible-name computation: first non-empty source wins.
// Elements are plain objects; ids map lets aria-labelledby find other nodes.
const byId = {
  hint: { text: 'Search the site' },
  lbl: { text: 'Email address' },
};

function accessibleName(el) {
  if (el.labelledby) {
    const t = el.labelledby.split(' ').map((id) => byId[id].text).join(' ').trim();
    if (t) return ['aria-labelledby', t];
  }
  if (el.ariaLabel && el.ariaLabel.trim()) return ['aria-label', el.ariaLabel.trim()];
  if (el.label) return ['label', el.label];          // native <label for>
  if (el.alt) return ['alt', el.alt];                // <img alt>
  if (el.text) return ['content', el.text];          // button/link text
  if (el.title) return ['title', el.title];          // weak, often not announced reliably
  if (el.placeholder) return ['placeholder', el.placeholder]; // weakest fallback
  return ['none', ''];
}

const cases = [
  { name: 'input with everything', labelledby: 'lbl', ariaLabel: 'ignored', label: 'also ignored' },
  { name: 'icon button', ariaLabel: 'Close dialog', text: '' },
  { name: 'text input', label: 'Full name', placeholder: 'Jane Doe' },
  { name: 'image', alt: 'Company logo', title: 'logo.png' },
  { name: 'link', text: 'Pricing', title: 'See pricing' },
  { name: 'only title', title: 'Help' },
  { name: 'only placeholder', placeholder: 'Search...' },
  { name: 'empty div' },
];
for (const c of cases) {
  const [src, name] = accessibleName(c);
  console.log(c.name.padEnd(22) + src.padEnd(16) + JSON.stringify(name));
}

// Roving tabindex + arrow-key navigation for a tabs widget (pure logic).
const tabs = ['Overview', 'Specs', 'Reviews', 'FAQ'];
let selected = 0;

function tabindexes() {
  // Only the selected tab is in the Tab order; the others are -1.
  return tabs.map((_, i) => (i === selected ? 0 : -1));
}

function onKey(key) {
  const n = tabs.length;
  if (key === 'ArrowRight') selected = (selected + 1) % n;       // wraps to first
  else if (key === 'ArrowLeft') selected = (selected - 1 + n) % n; // wraps to last
  else if (key === 'Home') selected = 0;
  else if (key === 'End') selected = n - 1;
  else return;
  // automatic activation: focus moves and the panel switches together
}

console.log('tabs:', tabs.join(', '));
console.log('start    ', JSON.stringify(tabindexes()), tabs[selected]);
for (const key of ['ArrowRight', 'ArrowRight', 'End', 'ArrowRight', 'ArrowLeft', 'Home', 'ArrowLeft']) {
  onKey(key);
  console.log(key.padEnd(10) + JSON.stringify(tabindexes()) + ' ' + tabs[selected]);
}
// One Tab stop for the whole list, so Tab leaves the tablist and enters the panel.

// Focus trap logic for a modal: Tab / Shift+Tab cycle inside, Escape closes,
// and focus returns to the opener. Pure logic with a fake page.
const page = { focus: 'open-button', dialogOpen: false };
const dialogItems = ['name-input', 'cancel-btn', 'save-btn'];
let opener = null;

function openDialog() {
  opener = page.focus;          // remember who opened it
  page.dialogOpen = true;
  page.focus = dialogItems[0];  // move focus inside
}
function closeDialog() {
  page.dialogOpen = false;
  page.focus = opener;          // restore focus to the opener
}
function onKey(key, shift) {
  if (!page.dialogOpen) return;
  if (key === 'Escape') return closeDialog();
  if (key === 'Tab') {
    const i = dialogItems.indexOf(page.focus);
    const n = dialogItems.length;
    // wrap around instead of leaving the dialog
    page.focus = dialogItems[(i + (shift ? -1 : 1) + n) % n];
  }
}

openDialog();
console.log('opened  focus =', page.focus);
const keys = [['Tab', false], ['Tab', false], ['Tab', false], ['Tab', true], ['Escape', false]];
for (const [k, s] of keys) {
  onKey(k, s);
  console.log((s ? 'Shift+' : '') + k.padEnd(8), 'focus =', page.focus, 'open =', page.dialogOpen);
}

