public class Main {
    // Linearise one sRGB channel (0..255)
    static double lin(int c) {
        double s = c / 255.0;
        return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    }
    // Relative luminance from 0xRRGGBB
    static double lum(int rgb) {
        return 0.2126 * lin((rgb >> 16) & 255) + 0.7152 * lin((rgb >> 8) & 255) + 0.0722 * lin(rgb & 255);
    }
    static double ratio(int a, int b) {
        double la = lum(a), lb = lum(b);
        double hi = Math.max(la, lb), lo = Math.min(la, lb);
        return (hi + 0.05) / (lo + 0.05); // lighter over darker
    }
    public static void main(String[] args) {
        int white = 0xFFFFFF;
        int[] fg = {0x000000, 0x767676, 0x777777, 0x0000FF, 0xAAAAAA};
        for (int c : fg) {
            double r = ratio(c, white);
            String verdict = r >= 7 ? "AAA" : r >= 4.5 ? "AA" : r >= 3 ? "large text/UI only" : "fail";
            System.out.printf("#%06x on #ffffff = %.2f:1 %s%n", c, r, verdict);
        }
    }
}

