// Toast announcer: one persistent live region, clear-then-write, dedupe, queue.
const region = { text: '', log: [] };       // stands in for <div aria-live="polite">
const queue = [];
const recent = new Map();                   // message -> last time announced
const DEDUPE_MS = 2000;

function announce(msg, now) {
  if (recent.has(msg) && now - recent.get(msg) < DEDUPE_MS) {
    console.log(now + 'ms dropped duplicate: ' + msg);
    return;
  }
  recent.set(msg, now);
  queue.push(msg);
}

function flush(now) {
  // Announce one message per tick so the screen reader is not flooded.
  const msg = queue.shift();
  if (!msg) return;
  region.text = '';          // clear first so an identical later message still counts as a change
  region.text = msg;         // the text change is what gets announced
  region.log.push(msg);
  console.log(now + 'ms announced: ' + msg);
}

announce('Saved', 0);
announce('Saved', 500);                 // duplicate within 2s, dropped
announce('Upload failed', 600);
announce('Saved', 3000);                // old enough, allowed again
for (const t of [3100, 3200, 3300]) flush(t);
console.log('announced in order:', JSON.stringify(region.log));
